const main=document.querySelector('#main');
const menu=document.querySelector('#menu-panel');
const menuToggle=document.querySelector('#menu-toggle');
let dispose=()=>{};
let archiveFilter='All',archiveSearch='',galleryArtist='all';
const card=a=>`<a class="artist-card" href="#/artist/${a.id}"><div class="portrait"><img src="${a.portrait}" alt="Portrait of ${a.name}" loading="lazy"></div><div class="card-top"><span>${a.years}</span><span>PAKISTAN</span></div><h3>${a.name}</h3><p class="card-field">${a.field}</p></a>`;
const workCard=w=>`<button class="work" data-work="${w.id}" aria-label="Enlarge ${w.label}, ${w.artist.name}"><div class="work-img"><img src="${w.src}" alt="Artwork associated with ${w.artist.name} in the supplied collection" loading="lazy"></div><div class="work-caption"><div>${w.artist.name}<small>${w.label}</small></div><span aria-hidden="true">↗</span></div></button>`;
const pageTitle=(eyebrow,title,copy)=>`<section class="page-title">${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h1>${title}</h1><p>${copy}</p></section>`;
const paths=()=>`<div class="path-menu">${[['The archive','Meet the women','archive'],['The gallery','Explore their work','gallery'],['A moment of discovery','Find the artist','discover'],['Our purpose','Why we remember','about']].map((v,i)=>`<a href="#/${v[2]}"><small>0${i+1}</small><h3>${v[0]}</h3><em>${v[1]}</em><b aria-hidden="true">↗</b></a>`).join('')}</div>`;
function closeMenu(){menu.hidden=true;menuToggle.setAttribute('aria-expanded','false')}
menuToggle.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;menuToggle.setAttribute('aria-expanded',String(open))});
document.querySelector('#close-menu').addEventListener('click',()=>{closeMenu();menuToggle.focus()});
menu.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
function renderHome(){main.innerHTML=`<section class="home-hero"><div class="hero-intro"><span class="eyebrow">AN ARCHIVE OF PAKISTANI WOMEN ARTISTS</span><h1>She created art.<br>She became <em>history.</em></h1></div><section class="dome-section" aria-label="Interactive artwork dome"><div class="dome" id="dome" aria-label="Rotating gallery. Drag to rotate or select an artwork."><div class="sphere" id="sphere"></div><div class="dome-shade"></div></div><div class="dome-caption"><span class="number">01</span><div><span class="eyebrow">THE LIVING COLLECTION</span><p>Drag to wander · Click to look closer</p></div></div><div class="dome-controls"><span>A different perspective</span><button class="round" id="rotate-left" aria-label="Rotate gallery left">←</button><button class="round" id="pause-dome" aria-label="Pause gallery" aria-pressed="false">Ⅱ</button><button class="round" id="rotate-right" aria-label="Rotate gallery right">→</button></div></section><div class="hero-action"><a class="button light" href="#/archive">Enter the Archive <span aria-hidden="true">↗</span></a></div></section><div class="collection-ribbon" aria-hidden="true"><div class="ribbon-track">${[0,1].map(()=>`<div class="ribbon-group">${[1,19,9,27,20,13,3,16,10,30,24,14].map(n=>`<img src="${asset(n)}" alt="" loading="lazy">`).join('')}</div>`).join('')}</div></div><section class="home-menu" aria-label="Explore Naqsh">${paths()}</section><section class="quote-band home-about"><h2>History holds<br>more than <em>one voice.</em></h2><div class="copy"><p>Pakistan’s cultural story was shaped by women who painted, taught, experimented, and made space for others.</p><p>Naqsh brings their contributions into view—one artist, one artwork, one story at a time.</p></div></section>`;setupDome()}
function setupDome(){const dome=document.querySelector('#dome'),sphere=document.querySelector('#sphere');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches,rotation=0,dragging=false,lastX=0,startX=0,startY=0,moved=false,raf,lastTime=0,radius,visible=true;
const tiles=[];for(let row=0;row<5;row++){for(let col=0;col<22;col++){const w=works[(col+row*7)%works.length];const b=document.createElement('button');b.className='dome-tile';b.dataset.work=w.id;b.setAttribute('aria-label',`View artwork from ${w.artist.name}`);b.tabIndex=-1;b.innerHTML=`<img src="${w.src}" alt="" draggable="false">`;sphere.append(b);tiles.push({b,row,col})}}
function size(){const width=dome.clientWidth;radius=Math.max(width*.53,350);dome.style.perspective=`${radius*3.6}px`;const tw=radius*.247,th=Math.min(radius*.17,dome.clientHeight*.15);const verticalRadius=Math.min(radius*.50,dome.clientHeight*.50);tiles.forEach(({b,row,col})=>{const lat=(row-2)*20;const lon=col*360/22+(row%2)*8;const la=lat*Math.PI/180;const lo=lon*Math.PI/180;const x=radius*Math.cos(la)*Math.sin(lo);const y=verticalRadius*Math.sin(la);const z=radius*Math.cos(la)*Math.cos(lo);b.style.width=`${tw}px`;b.style.height=`${th}px`;b.style.marginLeft=`${-tw/2}px`;b.style.marginTop=`${-th/2}px`;b.style.transform=`translate3d(${x}px,${y}px,${z}px) rotateY(${lon}deg) rotateX(${-lat}deg)`});sphere.style.transform=`rotateY(${rotation}deg)`}
const resize=new ResizeObserver(size);resize.observe(dome);size();
const pauseButton=document.querySelector('#pause-dome');function syncPause(){pauseButton.textContent=paused?'▷':'Ⅱ';pauseButton.setAttribute('aria-label',paused?'Play gallery':'Pause gallery');pauseButton.setAttribute('aria-pressed',String(paused))}syncPause();pauseButton.onclick=()=>{paused=!paused;syncPause()};document.querySelector('#rotate-left').onclick=()=>{rotation-=18;sphere.style.transform=`rotateY(${rotation}deg)`};document.querySelector('#rotate-right').onclick=()=>{rotation+=18;sphere.style.transform=`rotateY(${rotation}deg)`};
function tick(t){const dt=Math.min(t-lastTime,50);lastTime=t;if(!paused&&!dragging&&visible&&!document.hidden&&!lightbox.open){rotation+=dt*.0024;sphere.style.transform=`rotateY(${rotation}deg)`}raf=requestAnimationFrame(tick)}raf=requestAnimationFrame(tick);
const observer=new IntersectionObserver(([entry])=>visible=entry.isIntersecting);observer.observe(dome);
function motionChange(){if(reduced.matches){paused=true;syncPause()}}reduced.addEventListener('change',motionChange);
dome.addEventListener('pointerdown',e=>{if(e.button!==0)return;dragging=true;lastX=startX=e.clientX;startY=e.clientY;moved=false});
const move=e=>{if(!dragging)return;if(Math.abs(e.clientX-startX)>5||Math.abs(e.clientY-startY)>8)moved=true;if(Math.abs(e.clientX-startX)>Math.abs(e.clientY-startY)){rotation+=(e.clientX-lastX)*.12;sphere.style.transform=`rotateY(${rotation}deg)`}lastX=e.clientX};
const up=()=>{dragging=false};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up);
dome.addEventListener('click',e=>{if(moved){e.stopPropagation();return}const b=e.target.closest('[data-work]');if(b)openWork(b.dataset.work)});
dispose=()=>{cancelAnimationFrame(raf);resize.disconnect();observer.disconnect();reduced.removeEventListener('change',motionChange);window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up)};
}
function renderArchive(){main.innerHTML=pageTitle('','The Archive','Explore the lives and contributions behind the work.')+`<div class="archive-toolbar"><label class="search-wrap"><span aria-hidden="true">⌕</span><input type="search" id="artist-search" class="search" placeholder="Search an artist or practice…" aria-label="Search artists"></label><div class="filters" aria-label="Filter artists by practice">${['All','Painting','Modernism','Education','Contemporary'].map(x=>`<button class="filter ${archiveFilter===x?'active':''}" data-filter="${x}" aria-pressed="${archiveFilter===x}">${x}</button>`).join('')}</div></div><section class="section" style="padding-top:35px"><p id="archive-count" class="results-note" aria-live="polite"></p><div class="archive-grid" id="archive-results"></div></section>`;const search=document.querySelector('#artist-search');search.value=archiveSearch;function results(){const q=archiveSearch.toLowerCase();const list=artists.filter(a=>(archiveFilter==='All'||a.category===archiveFilter)&&`${a.name} ${a.field} ${a.intro}`.toLowerCase().includes(q));document.querySelector('#archive-count').textContent=`${String(list.length).padStart(2,'0')} artists in view`;document.querySelector('#archive-results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>No artists found.</h2><p>Try a different name or choose “All”.</p><button class="button outline" id="reset-search">Clear filters ↗</button></div>';document.querySelector('#reset-search')?.addEventListener('click',()=>{archiveSearch='';archiveFilter='All';renderArchive()})}search.oninput=()=>{archiveSearch=search.value;results()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{archiveFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});results()});results()}
function renderGallery(){main.innerHTML=pageTitle('','The gallery.','A closer look at the images in this collection. Select a work to enlarge it and discover its artist.')+`<div class="archive-toolbar"><label for="gallery-filter" class="eyebrow">EXPLORE BY ARTIST</label><select id="gallery-filter" class="search"><option value="all">All artists</option>${artists.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></div><section class="section" style="padding-top:35px"><p class="results-note" id="gallery-count" aria-live="polite"></p><div class="gallery-grid" id="gallery-results"></div><p class="collection-note">Artist associations follow the supplied reference pages. Original artwork titles, dates, media, and image credits were not supplied; collection labels are identifiers, not artwork titles. <a href="#/sources" class="text-link">Read the image notes ↗</a></p></section>`;const select=document.querySelector('#gallery-filter');select.value=galleryArtist;function results(){const list=works.filter(w=>galleryArtist==='all'||w.artist.id===galleryArtist);document.querySelector('#gallery-results').innerHTML=list.map(workCard).join('');document.querySelector('#gallery-count').textContent=`${list.length} collection images`};select.onchange=()=>{galleryArtist=select.value;results()};results()}
function renderArtist(id){const a=artists.find(a=>a.id===id);if(!a)return render404();const next=artists[(artists.indexOf(a)+1)%artists.length];main.innerHTML=`<div class="back-row"><a href="#/archive">← Back to the archive</a></div><section class="profile-title-band"><span class="eyebrow">${a.field} · PAKISTAN</span><h1>${a.name}</h1><p class="years">${a.years}</p></section><section class="profile-hero"><div class="profile-portrait"><img src="${a.portrait}" alt="Portrait of ${a.name}"></div><div class="profile-introduction"><span class="eyebrow">THE ARTIST BEHIND THE WORK</span><p class="intro">${a.intro}</p><p class="line">${a.line}</p></div></section><a href="#artist-works" class="collection-menu-row" id="view-works"><small>EXPLORE HER WORK</small><span>View the <em>Collection</em></span><b aria-hidden="true">↓</b></a><section class="section profile-story"><div><span class="eyebrow">HER LIFE & LEGACY</span><div class="milestone"><strong>${a.milestone}</strong><p>${a.event}</p></div></div><div class="story-copy"><h2>Who she was.<br>What she made possible.</h2><p>${a.story}</p><h2>Her practice.</h2><p>${a.practice}</p><h2>The mark she leaves.</h2><p>${a.legacy}</p><p class="source-note">Further reading: <a href="${a.source}" target="_blank" rel="noopener noreferrer">${a.sourceName} ↗</a>${a.extraSource?` · <a href="${a.extraSource}" target="_blank" rel="noopener noreferrer">${a.extraName} ↗</a>`:''}</p></div></section><section id="artist-works" class="section collection-section"><div class="section-heading"><div><span class="eyebrow">A CLOSER LOOK</span><h2>From her collection.</h2></div><span class="eyebrow">${a.art.length} IMAGES</span></div><div class="gallery-grid">${works.filter(w=>w.artist===a).map(workCard).join('')}</div><p class="collection-note">Artist associations follow the supplied reference pages. Artwork titles and dates were not provided. <a href="#/sources">See image notes ↗</a></p></section><a href="#/artist/${next.id}" class="profile-next"><div><span class="eyebrow">CONTINUE THROUGH THE ARCHIVE</span><h3>${next.name}</h3></div><span aria-hidden="true">↗</span></a>`;document.querySelector('#view-works').onclick=e=>{e.preventDefault();document.querySelector('#artist-works').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}}
function renderAbout(){main.innerHTML=pageTitle('ABOUT NAQSH','A mark that remains.','Naqsh means a mark, an impression. This archive asks whose marks we remember, and whose we need to look for again.')+`<section class="section purpose-summary"><p>Naqsh brings the lives, work, and contributions of Pakistani women artists into view. Their achievements are part of our cultural history, and this archive makes their stories easier to discover. Through portraits, artwork, and a short quiz, it invites visitors to look closer and get to know the women behind the work.</p><a href="#/archive" class="button">Meet the Women <span>↗</span></a></section>`}

function renderSources(){main.innerHTML=pageTitle('RESEARCH & DOCUMENTATION','Follow the sources.','A starting point for reading further, with a clear distinction between researched biographies and supplied collection images.')+`<section class="section reading-layout"><div><span class="eyebrow">THE WRITTEN RECORD</span><h2 style="margin-top:20px">Behind<br>the stories.</h2></div><div class="source-list">${artists.map(a=>`<a class="source-item" href="${a.source}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">${a.name}</span><h3>${a.sourceName} ↗</h3><p>Biographical context and contributions.</p></a>`).join('')}<a class="source-item" href="https://www.metmuseum.org/ko/essays/modern-art-in-west-and-east-pakistan" target="_blank" rel="noopener noreferrer"><span class="eyebrow">HISTORICAL CONTEXT</span><h3>The Metropolitan Museum of Art ↗</h3><p>Modern Art in West and East Pakistan.</p></a></div></section><section class="section collection-section reading-layout"><div><span class="eyebrow">COLLECTION NOTES</span><h2 style="margin-top:20px">Images &<br>attribution.</h2></div><div><article><h3>The supplied collection.</h3><p>Artwork and portrait images were provided for this thesis project. Artist associations follow the accompanying reference pages, rather than the ZIP’s folder names, which contain inconsistent groupings. The Zubeida Agha portrait is extracted from her supplied reference page.</p></article><article><h3>What the labels mean.</h3><p>“Collection image” is an identifier used within Naqsh. It is not an artwork title. Original titles, dates, materials, provenance, and individual image credits were not provided and are not invented here.</p></article><article><h3>A working archive.</h3><p>The biographical sources support the written profiles; they do not independently authenticate every supplied image. Collection attribution and image permissions should be confirmed with artists, estates, or rights holders before wider institutional use.</p><p>Copyright in the artworks and photographs remains with their respective rights holders.</p></article></div></section>`}
let quizIndex=0,quizScore=0,quizAnswered=false,quizSequence=[];
const quizPrompts=['Which artist is connected to this work?','Who is the woman behind this image?','Can you match this work to its artist?','Whose collection does this image belong to?','Which artist would you explore to find this work?','Who created the work shown here?'];
const quizFacts={
'anna-molka-ahmed':[
['Who founded the Fine Arts Department at the University of the Punjab in 1940?','Her contribution helped create a lasting foundation for arts education in Lahore.'],
['Which artist helped shape generations of students at Punjab University?','Her legacy includes both her own painting and the opportunities she created through teaching.']],
'zubeida-agha':[
['Which artist helped pioneer modernist painting in Pakistan?','Her practice explored colour, space, and abstraction.'],
['Whose geometric abstraction was featured at Biennale Arte 2024?','La Biennale di Venezia places her among women who built a counternarrative of post-war abstraction.']],
'laila-shahzada':[
['Whose Drift Moods series was inspired by weathered driftwood?','The series was exhibited in 1964.'],
['Which artist created a Moenjodaro series inspired by the Indus Valley Civilisation?','Her painting connected modern expression with the region’s ancient cultural past.']],
'salima-hashmi':[
['Who wrote Unveiling the Visible: Lives and Works of Women Artists of Pakistan?','The book was published in 2002.'],
['Which artist was the founding dean of BNU’s visual arts and design school?','Her work spans painting, education, curation, and writing.']],
'shahzia-sikander':[
['Who created the breakthrough miniature work The Scroll in 1989–90?','This work challenged the conventions of miniature painting.'],
['Who became the first woman to teach in NCA’s Miniature Painting Department?','She trained with master miniaturist Bashir Ahmad.']],
'nahid-raza':[
['Who established Studio Art in Karachi in 1992?','Alongside exhibiting, she helped nurture emerging artists.'],
['Which artist presented work from her Virdh series at Karachi Biennale 2017?','Repeated motifs in this series reflect on incantation, devotion, and inner experience.']]
};
function shuffled(items){const result=[...items];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
let previousQuizIds=[];try{const saved=JSON.parse(sessionStorage.getItem('naqsh-previous-quiz')||'[]');if(Array.isArray(saved))previousQuizIds=saved}catch{}
function newQuiz(){quizIndex=0;quizScore=0;quizAnswered=false;const kinds=shuffled(['image','image','image','story','story','story']);const prompts=shuffled(quizPrompts);quizSequence=shuffled(artists).map((a,i)=>{const pool=kinds[i]==='image'?works.filter(w=>w.artist===a).map(w=>({...w,type:'image',questionId:w.id,prompt:prompts[i],hint:'Look at the colour, the forms, and the feeling. Then choose a name.'})):quizFacts[a.id].map(([prompt,hint],j)=>({artist:a,src:a.portrait,type:'story',questionId:`${a.id}-story-${j}`,prompt,hint}));const unused=pool.filter(q=>!previousQuizIds.includes(q.questionId));return shuffled(unused.length?unused:pool)[0]});previousQuizIds=quizSequence.map(q=>q.questionId);try{sessionStorage.setItem('naqsh-previous-quiz',JSON.stringify(previousQuizIds))}catch{}}
function renderDiscover(){if(!quizSequence.length)newQuiz();if(quizAnswered&&quizIndex<quizSequence.length){quizIndex++;quizAnswered=false}main.innerHTML=pageTitle('','Look first. Discover next.','A six-question quiz about the artists, their work, and their contributions. Each attempt brings a different mix.')+'<section class="section" id="quiz"></section>';renderQuiz()}
function renderQuiz(){const area=document.querySelector('#quiz');if(quizIndex>=quizSequence.length){area.innerHTML=`<div class="quote-band"><div><span class="eyebrow">QUIZ COMPLETE</span><h2>${quizScore} of 6<br><em>connections made.</em></h2></div><div class="copy"><p>Every name you discovered is another story to carry forward. Keep exploring the artists and the work they made possible.</p><a class="button" href="#/archive">Explore their stories ↗</a><p style="margin-top:25px"><button id="restart-quiz" class="text-link">Try a new quiz ↻</button></p></div></div>`;document.querySelector('#restart-quiz').onclick=()=>{newQuiz();renderQuiz()};return}
quizAnswered=false;const w=quizSequence[quizIndex];const correct=w.artist;const options=shuffled([correct,...shuffled(artists.filter(a=>a!==correct)).slice(0,3)]);area.innerHTML=`<div class="quiz-layout"><div class="quiz-image"><img src="${w.src}" alt="${w.type==='image'?'Artwork from the collection. Choose the associated artist.':'Artist portrait. Choose the artist described in the question.'}"></div><div class="quiz-info"><div class="quiz-progress"><span>QUESTION ${String(quizIndex+1).padStart(2,'0')} / 06</span><span>${quizScore} correct</span></div><span class="eyebrow" style="display:block;margin-top:25px">${w.type==='image'?'MATCH THE ARTWORK':'KNOW HER STORY'}</span><h2>${w.prompt}</h2><p>${w.hint}</p><div class="quiz-options">${options.map(a=>`<button class="quiz-choice" data-answer="${a.id}">${a.name}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div></div></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(quizAnswered)return;quizAnswered=true;const right=b.dataset.answer===correct.id;if(right)quizScore++;document.querySelectorAll('[data-answer]').forEach(x=>{x.disabled=true;if(x.dataset.answer===correct.id)x.classList.add('correct')});if(!right)b.classList.add('incorrect');document.querySelector('#quiz-feedback').innerHTML=`<div class="quiz-feedback"><h3>${right?'A connection made.':'A new name to remember.'}</h3><p>${w.type==='image'?'This collection image is associated with':'The answer is'} <strong>${correct.name}</strong>.</p><p>${w.type==='image'?correct.line:w.hint}</p><a href="#/artist/${correct.id}">Read her story ↗</a></div><button class="button" id="next-question">${quizIndex===5?'See your results':'Next question'} →</button>`;document.querySelector('#next-question').onclick=()=>{quizIndex++;renderQuiz()}})}

function render404(){main.innerHTML=`<div class="error-view"><h1>This page is still a blank canvas.</h1><p>Return to the archive to find an artist or artwork.</p><a class="button" href="#/archive">Back to the archive ↗</a></div>`}
const lightbox=document.querySelector('#lightbox');let lightboxList=works,lightboxIndex=0;function showLightbox(){const w=lightboxList[lightboxIndex];document.querySelector('#lightbox-img').src=w.src;document.querySelector('#lightbox-img').alt=`${w.label}, associated with ${w.artist.name} in the supplied collection`;document.querySelector('#lightbox-title').textContent=w.artist.name;document.querySelector('#lightbox-caption').textContent=`${w.label} · Title and date not supplied.`;document.querySelector('#lightbox-artist').href=`#/artist/${w.artist.id}`;document.querySelector('#lightbox-count').textContent=`${lightboxIndex+1} / ${lightboxList.length}`}
function openWork(id){const w=works.find(w=>w.id===id);if(!w)return;const path=location.hash.slice(1);lightboxList=path.startsWith('/artist/')?works.filter(x=>x.artist===w.artist):path==='/gallery'&&galleryArtist!=='all'?works.filter(x=>x.artist.id===galleryArtist):works;lightboxIndex=lightboxList.indexOf(w);showLightbox();if(!lightbox.open)lightbox.showModal()}
document.querySelector('.dialog-close').onclick=()=>lightbox.close();lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});document.querySelector('#previous-art').onclick=()=>{lightboxIndex=(lightboxIndex-1+lightboxList.length)%lightboxList.length;showLightbox()};document.querySelector('#next-art').onclick=()=>{lightboxIndex=(lightboxIndex+1)%lightboxList.length;showLightbox()};lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();document.querySelector('#next-art').click()}if(e.key==='ArrowLeft'){e.preventDefault();document.querySelector('#previous-art').click()}});document.querySelector('#lightbox-artist').onclick=()=>lightbox.close();
main.addEventListener('click',e=>{const button=e.target.closest('[data-work]');if(button&&!button.classList.contains('dome-tile'))openWork(button.dataset.work)});
function route(){dispose();dispose=()=>{};closeMenu();if(lightbox.open)lightbox.close();const path=location.hash.slice(1)||'/';if(path==='/')renderHome();else if(path==='/archive')renderArchive();else if(path==='/gallery')renderGallery();else if(path==='/about')renderAbout();else if(path==='/sources')renderSources();else if(path==='/discover')renderDiscover();else if(path.startsWith('/artist/'))renderArtist(path.split('/')[2]);else render404();const page=path.startsWith('/artist/')?artists.find(a=>a.id===path.split('/')[2])?.name:path==='/'?'Her Art. Our History.':path.slice(1).replace(/^./,x=>x.toUpperCase());document.title=`${page||'Page not found'} — Naqsh`;window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});document.querySelectorAll('.masthead nav>a').forEach(a=>{if(a.hash===location.hash)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
window.addEventListener('hashchange',route);route();
